package memory

// This memory shape is made to match the ATIF format
// See: https://github.com/laude-institute/harbor/blob/main/docs/rfcs/0001-trajectory-format.md
// This is meant to follow standards and will be later stored in db for tracking and analysis

type MemoryEntry struct {
	StepID           int                    `json:"step_id"`
	Timestamp        string                 `json:"timestamp,omitempty"`
	Source           string                 `json:"source"`
	ModelName        string                 `json:"model_name,omitempty"`
	ReasoningEffort  interface{}            `json:"reasoning_effort,omitempty"`
	Message          string                 `json:"message"`
	ReasoningContent string                 `json:"reasoning_content,omitempty"`
	ToolCalls        []ToolCall             `json:"tool_calls,omitempty"`
	Observation      Observation            `json:"observation,omitempty"`
	Metrics          Metrics                `json:"metrics,omitempty"`
	Extra            map[string]interface{} `json:"extra,omitempty"`
}

type ToolCall struct {
	ToolCallID   string                 `json:"tool_call_id"`
	FunctionName string                 `json:"function_name"`
	Arguments    map[string]interface{} `json:"arguments"`
}

type Observation struct {
	Results []ObservationResult `json:"results,omitempty"`
}

type ObservationResult struct {
	SourceCallID          string                  `json:"source_call_id,omitempty"`
	Content               string                  `json:"content,omitempty"`
	SubagentTrajectoryRef []SubagentTrajectoryRef `json:"subagent_trajectory_ref,omitempty"`
}

type SubagentTrajectoryRef struct {
	SessionID      string                 `json:"session_id"`
	TrajectoryPath string                 `json:"trajectory_path,omitempty"`
	Extra          map[string]interface{} `json:"extra,omitempty"`
}

type Metrics struct {
	PromptTokens       int                    `json:"prompt_tokens,omitempty"`
	CompletionTokens   int                    `json:"completion_tokens,omitempty"`
	CachedTokens       int                    `json:"cached_tokens,omitempty"`
	CostUSD            float64                `json:"cost_usd,omitempty"`
	PromptTokenIDs     []int                  `json:"prompt_token_ids,omitempty"`
	CompletionTokenIDs []int                  `json:"completion_token_ids,omitempty"`
	Logprobs           []float64              `json:"logprobs,omitempty"`
	Extra              map[string]interface{} `json:"extra,omitempty"`
}

package bridge

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sync/atomic"
	"time"

	"github.com/mightymoud/arlocode/internal/butler/agent"
	"github.com/mightymoud/arlocode/internal/butler/memory"
	"github.com/mightymoud/arlocode/internal/butler/tools"
)

type DirectBridge struct {
	agent      *agent.Agent
	events     chan AgentEvent
	cancelFn   context.CancelFunc
	responding atomic.Bool
}

func NewDirectBridge(a *agent.Agent) *DirectBridge {
	db := &DirectBridge{
		agent:  a,
		events: make(chan AgentEvent, 100),
	}
	db.agent.
		WithOnTextChunk(func(s string) {
			db.events <- TextChunkEvent{Text: s}
		}).
		WithOnTextComplete(func() {
			db.events <- TextCompleteEvent{}
		}).
		WithOnThinkingChunk(func(s string) {
			db.events <- ThinkingChunkEvent{Text: s}
		}).
		WithOnThinkingComplete(func() {
			db.events <- ThinkingCompleteEvent{}
		}).
		WithOnToolCall(func(tc tools.ToolCall) {
			db.events <- ToolCallEvent{ToolCall: tc}
		}).
		WithOnTurnComplete(func() {
			db.events <- TurnCompleteEvent{}
		})

	return db
}

func (db *DirectBridge) Run(ctx context.Context, prompt string) error {
	ctx, db.cancelFn = context.WithCancel(ctx)
	db.responding.Store(true)

	go func() {
		err := db.agent.Run(ctx, prompt)
		db.responding.Store(false)
		if err != nil {
			db.events <- ErrorEvent{Err: err}
		}
		db.events <- TurnCompleteEvent{}
	}()

	return nil
}

func (db *DirectBridge) IsResponding() bool {
	return db.responding.Load()
}

func (db *DirectBridge) Events() <-chan AgentEvent {
	return db.events
}

func (db *DirectBridge) Cancel() error {
	if db.cancelFn != nil {
		db.cancelFn()
	}
	return nil
}
func (db *DirectBridge) Close() error {
	close(db.events)
	return nil
}

type atifAgent struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type atifTrajectory struct {
	SchemaVersion string           `json:"schema_version"`
	SessionID     string           `json:"session_id"`
	Agent         atifAgent        `json:"agent"`
	Steps         []atifStep       `json:"steps"`
	FinalMetrics  atifFinalMetrics `json:"final_metrics"`
}

type atifFinalMetrics struct {
	TotalPromptTokens     int                    `json:"total_prompt_tokens,omitempty"`
	TotalCompletionTokens int                    `json:"total_completion_tokens,omitempty"`
	TotalCachedTokens     int                    `json:"total_cached_tokens,omitempty"`
	TotalCostUSD          float64                `json:"total_cost_usd,omitempty"`
	TotalSteps            int                    `json:"total_steps"`
	Extra                 map[string]interface{} `json:"extra,omitempty"`
}

type atifStep struct {
	StepID           int                    `json:"step_id"`
	Timestamp        string                 `json:"timestamp,omitempty"`
	Source           string                 `json:"source"`
	ModelName        string                 `json:"model_name,omitempty"`
	ReasoningEffort  interface{}            `json:"reasoning_effort,omitempty"`
	Message          string                 `json:"message"`
	ReasoningContent string                 `json:"reasoning_content,omitempty"`
	ToolCalls        []memory.ToolCall      `json:"tool_calls,omitempty"`
	Observation      *memory.Observation    `json:"observation,omitempty"`
	Metrics          *memory.Metrics        `json:"metrics,omitempty"`
	Extra            map[string]interface{} `json:"extra,omitempty"`
}

func (db *DirectBridge) ExportATIF(path string) error {
	steps := db.agent.GetMemory()
	exportSteps := make([]atifStep, 0, len(steps))

	final := atifFinalMetrics{
		TotalSteps: len(steps),
	}

	for _, step := range steps {
		exportStep := atifStep{
			StepID:           step.StepID,
			Timestamp:        step.Timestamp,
			Source:           step.Source,
			ModelName:        step.ModelName,
			ReasoningEffort:  step.ReasoningEffort,
			Message:          step.Message,
			ReasoningContent: step.ReasoningContent,
			ToolCalls:        step.ToolCalls,
			Extra:            step.Extra,
		}

		if hasObservation(step.Observation) {
			obs := step.Observation
			exportStep.Observation = &obs
		}
		if hasMetrics(step.Metrics) {
			m := step.Metrics
			exportStep.Metrics = &m

			final.TotalPromptTokens += m.PromptTokens
			final.TotalCompletionTokens += m.CompletionTokens
			final.TotalCachedTokens += m.CachedTokens
			final.TotalCostUSD += m.CostUSD
		}

		exportSteps = append(exportSteps, exportStep)
	}

	traj := atifTrajectory{
		SchemaVersion: "ATIF-v1.5",
		SessionID:     fmt.Sprintf("session-%d", time.Now().UnixNano()),
		Agent: atifAgent{
			Name:    "arlocode",
			Version: "unknown",
		},
		Steps:        exportSteps,
		FinalMetrics: final,
	}

	bytes, err := json.MarshalIndent(traj, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, bytes, 0644)
}

func hasObservation(obs memory.Observation) bool {
	return len(obs.Results) > 0
}

func hasMetrics(m memory.Metrics) bool {
	return m.PromptTokens != 0 ||
		m.CompletionTokens != 0 ||
		m.CachedTokens != 0 ||
		m.CostUSD != 0 ||
		len(m.PromptTokenIDs) > 0 ||
		len(m.CompletionTokenIDs) > 0 ||
		len(m.Logprobs) > 0 ||
		(len(m.Extra) > 0)
}

package app

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/mightymoud/arlocode/internal/bridge"
	"github.com/mightymoud/arlocode/internal/butler/tools"
)

// Update handles all messages and routes them to the appropriate screen
func (m AppModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	var cmds []tea.Cmd

	// CRITICAL: Update viewport content BEFORE processing scroll events
	// The viewport needs content to know what can be scrolled
	if m.ChatScreen.Viewport.Width > 0 {
		baseStyle := lipgloss.NewStyle().Faint(m.showModal)
		content := m.buildConversationContent(m.ChatScreen.Viewport.Width, baseStyle)
		m.ChatScreen.Viewport.SetContent(content)
	}

	// Handle auto-scroll flag (set by previous Update, before View was called)
	if m.ChatScreen.ShouldScrollToBottom {
		m.ChatScreen.Viewport.GotoBottom()
		m.ChatScreen.ShouldScrollToBottom = false
	}

	m.ChatScreen.Viewport, cmd = m.ChatScreen.Viewport.Update(msg)
	cmds = append(cmds, cmd)

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.Notifications.UpdateScreenSize(msg.Width, msg.Height)
	}

	// Handle mouse events first before textinput can process them
	if mouseMsg, ok := msg.(tea.MouseMsg); ok {
		// Forward mouse wheel events to viewport for scrolling
		if m.currentScreen == ScreenChat && !m.showModal {
			// Check if it's a scroll event using IsWheel()
			mouseEvent := tea.MouseEvent(mouseMsg)
			if mouseEvent.IsWheel() {
				m.ChatScreen.Viewport, cmd = m.ChatScreen.Viewport.Update(msg)
				// fmt.Print(m.ChatScreen.Viewport.Height, "vueport height\n")
				// fmt.Print(m.ChatScreen.Viewport.Width)
				cmds = append(cmds, cmd)
				return m, tea.Batch(cmds...)
			}
		}
	}

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.Notifications.UpdateScreenSize(msg.Width, msg.Height)

		// Update viewport size when window changes
		// Calculate chat content height (total height - input area - status bar - margins)
		chatContentHeight := msg.Height - 5 - 1 - 2
		sidebarWidth := 30
		mainAreaWidth := msg.Width - sidebarWidth - 2

		if chatContentHeight > 0 && mainAreaWidth > 0 {
			m.ChatScreen.Viewport.Width = mainAreaWidth
			m.ChatScreen.Viewport.Height = chatContentHeight
		}

	case tickLoadingMsg:
		m.loadingFrame += 0.4
		cmds = append(cmds, TickLoading())
		return m, tea.Batch(cmds...)

	case tickMsg:
		// Update notification animations
		if m.Notifications.Update() {
			cmds = append(cmds, tickCmd())
		}
		return m, tea.Batch(cmds...)

	case AgentTextChunkMsg:
		// Create new agent message on first chunk
		if !m.ChatScreen.Conversation.GetLastMessage().IsType("agent") {
			m.ChatScreen.Conversation.StartAgentMessage()
			time.Sleep(100 * time.Millisecond)
		}
		m.ChatScreen.Conversation.UpdateAgentMessage(string(msg))
		// Flag to scroll to bottom when streaming - consumed by View
		m.ChatScreen.ShouldScrollToBottom = true
		return m, tea.Batch(cmds...)

	case AgentTextCompleteMsg:
		m.ChatScreen.Conversation.CompleteAgentMessage()
		m.ChatScreen.ShouldScrollToBottom = true
		return m, tea.Batch(cmds...)

	case AgentThinkingChunkMsg:
		// Create new thinking message on first chunk
		if !m.ChatScreen.Conversation.AgentThinking || !m.ChatScreen.Conversation.GetLastMessage().IsType("thinking") {
			m.ChatScreen.Conversation.StartThinkingMessage()
		}
		m.ChatScreen.Conversation.UpdateThinkingMessage(string(msg))
		m.ChatScreen.ShouldScrollToBottom = true
		return m, tea.Batch(cmds...)

	case AgentThinkingCompleteMsg:
		m.ChatScreen.Conversation.CompleteAgentThinkingMessage()
		m.ChatScreen.ShouldScrollToBottom = true
		return m, tea.Batch(cmds...)

	case ToolCallMsg:
		tc := tools.ToolCall(msg)
		m.ChatScreen.Conversation.AddToolCallMessage(tc)
		time.Sleep(100 * time.Millisecond)

		m.ChatScreen.ShouldScrollToBottom = true
		return m, tea.Batch(cmds...)

	case tea.KeyMsg:
		// Handle global key bindings first
		switch msg.String() {
		case "ctrl+c":
			return m, m.cleanup()

		// useful for debugging
		case "ctrl+s":
			// Save conversation history to internal/tui/app/msg.json
			data, err := json.MarshalIndent(m.ChatScreen.Conversation.Conversation, "", "  ")
			if err != nil {
				m.Notifications.PushError("Save Failed", "failed to marshal conversation")
				return m, nil
			}

			outPath := filepath.Join("internal", "tui", "app", "msg.json")
			err = os.WriteFile(outPath, data, 0644)
			if err != nil {
				m.Notifications.PushError("Save Failed", "failed to write msg.json")
				return m, nil
			}
			m.Notifications.PushSuccess("Saved", "Conversation saved to msg.json")
			return m, nil

		case "esc":
			if m.showModal {
				m.showModal = false
				m.ModalInput.Blur()
				m.focusCurrentScreenInput()
				// Get blink command for the focused input
				cmds = append(cmds, m.getCurrentScreenBlinkCmd())
				return m, tea.Batch(cmds...)
			}
			return m, nil
		case "ctrl+o":
			// Toggle modal
			m.showModal = !m.showModal
			if m.showModal {
				m.blurCurrentScreenInput()
				m.ModalInput.Focus()
				// Get blink command for modal input
				cmds = append(cmds, m.ModalInput.Cursor.BlinkCmd())
			} else {
				m.ModalInput.Blur()
				m.focusCurrentScreenInput()
				// Get blink command for the focused input
				cmds = append(cmds, m.getCurrentScreenBlinkCmd())
			}
			return m, tea.Batch(cmds...)
			// case "w":
			// 	// Show warning notification
			// 	if !m.showModal {
			// 		m.Notifications.PushWarning("Warning", "This is a warning notification!")
			// 		cmds = append(cmds, tickCmd())
			// 		return m, tea.Batch(cmds...)
			// 	}
		}

		// Handle modal input
		if m.showModal {
			if msg.String() == "enter" {
				// Close modal on enter
				m.showModal = false
				m.ModalInput.Blur()
				m.focusCurrentScreenInput()
				// Get blink command for the focused input
				cmds = append(cmds, m.getCurrentScreenBlinkCmd())
			}
			return m, tea.Batch(cmds...)
		}

		// Route key input to the current screen
		switch m.currentScreen {
		case ScreenWelcome:
			m, cmd = m.handleWelcomeScreenKeys(msg)
			cmds = append(cmds, cmd)
		case ScreenChat:
			m, cmd = m.handleChatScreenKeys(msg)
			cmds = append(cmds, cmd)
		}
	}

	// Always update the focused textinput with all messages (for cursor blinking)
	if m.showModal {
		m.ModalInput, cmd = m.ModalInput.Update(msg)
		cmds = append(cmds, cmd)
	} else {
		switch m.currentScreen {
		case ScreenWelcome:
			m.WelcomeScreen.Input, cmd = m.WelcomeScreen.Input.Update(msg)
			cmds = append(cmds, cmd)
		case ScreenChat:
			m.ChatScreen.Input, cmd = m.ChatScreen.Input.Update(msg)
			cmds = append(cmds, cmd)
		}
	}

	return m, tea.Batch(cmds...)
}

// handleWelcomeScreenKeys handles key events for the welcome screen
func (m AppModel) handleWelcomeScreenKeys(msg tea.KeyMsg) (AppModel, tea.Cmd) {
	switch msg.String() {
	case "enter":
		value := m.WelcomeScreen.Input.Value()
		if value != "" {
			// Clear input and transition to chat screen
			m.WelcomeScreen.Input.SetValue("")
			m.currentScreen = ScreenChat
			m.WelcomeScreen.Input.Blur()
			m.ChatScreen.Input.Focus()
			// Add user message to conversation
			m.ChatScreen.Conversation.AddUserMessage(value)
			// Start the agent
			m.Bridge.Run(context.Background(), value)
			return m, tickCmd()
		}
	}
	return m, nil
}

// handleChatScreenKeys handles key events for the chat screen
func (m AppModel) handleChatScreenKeys(msg tea.KeyMsg) (AppModel, tea.Cmd) {
	switch msg.String() {
	case "enter":
		value := m.ChatScreen.Input.Value()
		if value != "" {
			// Clear input after submission
			m.ChatScreen.Input.SetValue("")
			// Add user message to conversation
			m.ChatScreen.Conversation.AddUserMessage(value)
			// Start the agent
			m.Bridge.Run(context.Background(), value)
			return m, tickCmd()
		}
	}
	return m, nil
}

// focusCurrentScreenInput focuses the input of the current screen
func (m *AppModel) focusCurrentScreenInput() {
	switch m.currentScreen {
	case ScreenWelcome:
		m.WelcomeScreen.Input.Focus()
	case ScreenChat:
		m.ChatScreen.Input.Focus()
	}
}

// blurCurrentScreenInput blurs the input of the current screen
func (m *AppModel) blurCurrentScreenInput() {
	switch m.currentScreen {
	case ScreenWelcome:
		m.WelcomeScreen.Input.Blur()
	case ScreenChat:
		m.ChatScreen.Input.Blur()
	}
}

// getCurrentScreenBlinkCmd returns the blink command for the current screen's input
func (m *AppModel) getCurrentScreenBlinkCmd() tea.Cmd {
	switch m.currentScreen {
	case ScreenWelcome:
		return m.WelcomeScreen.Input.Cursor.BlinkCmd()
	case ScreenChat:
		return m.ChatScreen.Input.Cursor.BlinkCmd()
	}
	return nil
}

// cleanup cancels any inflight requests and closes the bridge before quitting
func (m *AppModel) cleanup() tea.Cmd {
	return func() tea.Msg {
		if db, ok := m.Bridge.(*bridge.DirectBridge); ok {
			_ = db.ExportATIF(filepath.Join(".", "atif_trajectory.json"))
		}
		// Cancel any inflight API requests
		if m.Bridge != nil {
			m.Bridge.Cancel()
			m.Bridge.Close()
		}
		return tea.Quit()
	}
}

package agent

import (
	"context"
	"encoding/json"
